<?php include 'config.php'; $msg=''; if(isset($_GET['delete'])) mysqli_query($conn,'DELETE FROM movies WHERE id='.(int)$_GET['delete']);
if($_SERVER['REQUEST_METHOD']=='POST'){ $title=trim($_POST['title']); $director=trim($_POST['director']); $year=(int)$_POST['release_year']; $genre=trim($_POST['genre']); if($title==''||$director==''||$year<1900||$year>2025||$genre==''){$msg='Enter valid movie details';} else {$id=(int)($_POST['id']??0); if($id>0){$stmt=mysqli_prepare($conn,'UPDATE movies SET title=?,director=?,release_year=?,genre=? WHERE id=?'); mysqli_stmt_bind_param($stmt,'ssisi',$title,$director,$year,$genre,$id);}else{$stmt=mysqli_prepare($conn,'INSERT INTO movies(title,director,release_year,genre) VALUES(?,?,?,?)'); mysqli_stmt_bind_param($stmt,'ssis',$title,$director,$year,$genre);} mysqli_stmt_execute($stmt);}}
$genre=mysqli_real_escape_string($conn,$_GET['genre']??''); $query=$genre?"SELECT * FROM movies WHERE genre='$genre'":"SELECT * FROM movies"; $res=mysqli_query($conn,$query); ?>
<!DOCTYPE html><html><head><title>Q17 Movies</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><h1>Movie Database Manager</h1><form method="post"><input name="id" placeholder="ID for edit"><input name="title" placeholder="Title"><input name="director" placeholder="Director"><input name="release_year" placeholder="Release Year"><input name="genre" placeholder="Genre"><button>Save Movie</button></form><p class="error"><?php echo $msg; ?></p><form method="get"><select name="genre"><option value="">All</option><option>Action</option><option>Drama</option><option>Comedy</option><option>Horror</option></select><button>Filter</button></form><table><tr><th>ID</th><th>Title</th><th>Director</th><th>Year</th><th>Genre</th><th>Action</th></tr><?php while($r=mysqli_fetch_assoc($res)){ ?><tr><td><?php echo $r['id']; ?></td><td><?php echo $r['title']; ?></td><td><?php echo $r['director']; ?></td><td><?php echo $r['release_year']; ?></td><td><?php echo $r['genre']; ?></td><td><a onclick="return confirmDelete()" href="?delete=<?php echo $r['id']; ?>">Delete</a></td></tr><?php } ?></table></div><script src="script.js"></script></body></html>
